import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import Navbar               from './components/Navbar';
import Home                 from './components/Home';
import Login                from './pages/Login';
import Register             from './pages/Register';
import OrganizerDashboard   from './features/dashboard/organizer/OrganizerDashboard';
import AttendeeDashboard    from './features/dashboard/attendee/AttendeeDashboard';

function App() {
  // simple helper to check auth
  const isAuthenticated = !!localStorage.getItem('token');
  const user            = JSON.parse(localStorage.getItem('user') || 'null');

  return (
    <BrowserRouter>
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />

        <Route
          path="/login"
          element={isAuthenticated ? <Navigate to="/" /> : <Login />}
        />
        <Route
          path="/register"
          element={isAuthenticated ? <Navigate to="/" /> : <Register />}
        />

        <Route
          path="/organizer/dashboard"
          element={
            isAuthenticated && user?.role === 'organizer'
              ? <OrganizerDashboard />
              : <Navigate to="/login" />
          }
        />

        <Route
          path="/attendee/dashboard"
          element={
            isAuthenticated && user?.role === 'attendee'
              ? <AttendeeDashboard />
              : <Navigate to="/login" />
          }
        />

        {/* catch‐all redirect to home */}
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
